import { NextResponse } from 'next/server';
import { withApi, notFound, errorResponse } from '@/lib/api/handler';
import { markCancelled } from '@/lib/agent/state';
import { appError } from '@/lib/util/errors';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Params = { params: Promise<{ id: string }> };

export async function POST(request: Request, { params }: Params) {
  const { id } = await params;
  return withApi(request, async (ctx) => {
    const run = ctx.repos.runs.get(id);
    if (!run || run.userId !== ctx.userId) throw notFound('Run');
    if (['completed', 'failed', 'cancelled'].includes(run.status)) {
      return errorResponse(
        appError('VALIDATION_FAILED', 'Run ist bereits beendet', {
          userMessage: 'Dieser Run ist bereits beendet.',
        }),
        409,
      );
    }
    markCancelled(run.id, ctx.repos);
    return NextResponse.json({ run: ctx.repos.runs.get(run.id) });
  });
}

/** SSE-Stream des Execution Trace (Spec 09). */
import { apiContext, errorResponse } from '@/lib/api/handler';
import { appError, redact } from '@/lib/util/errors';
import { TERMINAL_EVENTS } from '@/lib/contracts/events';
import { getConfig } from '@/lib/config/env';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Params = { params: Promise<{ id: string }> };

export async function GET(request: Request, { params }: Params) {
  const { id } = await params;
  const ctx = apiContext(request);
  const config = getConfig();
  const run = ctx.repos.runs.get(id);
  if (!run || run.userId !== ctx.userId) {
    return errorResponse(appError('NOT_FOUND', 'Run nicht gefunden'), 404);
  }

  const url = new URL(request.url);
  const lastEventId = request.headers.get('last-event-id');
  const afterParam = url.searchParams.get('after');
  let cursor = Number(lastEventId ?? afterParam ?? 0);
  if (!Number.isFinite(cursor) || cursor < 0) cursor = 0;

  const encoder = new TextEncoder();
  const startedAt = Date.now();

  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      let closed = false;
      let lastHeartbeat = Date.now();

      const close = () => {
        if (closed) return;
        closed = true;
        try {
          controller.close();
        } catch {
          /* bereits geschlossen */
        }
      };

      request.signal.addEventListener('abort', close, { once: true });

      const send = (chunk: string) => {
        if (closed) return;
        try {
          controller.enqueue(encoder.encode(chunk));
        } catch {
          closed = true;
        }
      };

      send(': verbunden\n\n');

      while (!closed) {
        let terminal = false;
        try {
          const events = ctx.repos.events.listByRun(id, cursor, 200);
          for (const event of events) {
            cursor = event.seq;
            // Zusätzliche Redaction direkt vor dem Senden (Spec 09, Security)
            send(`id: ${event.seq}\nevent: ${event.type}\ndata: ${redact(JSON.stringify(event))}\n\n`);
            if (TERMINAL_EVENTS.has(event.type)) terminal = true;
          }
        } catch {
          send(`event: run.failed\ndata: ${JSON.stringify({ type: 'run.failed', payload: { code: 'INTERNAL', userMessage: 'Stream unterbrochen.' } })}\n\n`);
          break;
        }

        if (terminal) break;
        if (Date.now() - startedAt > config.SSE_MAX_DURATION_MS) break;
        if (Date.now() - lastHeartbeat > config.SSE_HEARTBEAT_MS) {
          send(': ping\n\n');
          lastHeartbeat = Date.now();
        }
        await new Promise((resolve) => setTimeout(resolve, config.SSE_POLL_INTERVAL_MS));
      }
      close();
    },
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream; charset=utf-8',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no',
    },
  });
}

import { NextResponse } from 'next/server';
import { withApi, notFound } from '@/lib/api/handler';
import { getConfig } from '@/lib/config/env';
import { isRunActive } from '@/lib/agent/state';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Params = { params: Promise<{ id: string }> };

export async function GET(request: Request, { params }: Params) {
  const { id } = await params;
  return withApi(request, async (ctx) => {
    const run = ctx.repos.runs.get(id);
    if (!run || run.userId !== ctx.userId) throw notFound('Run');

    // Verwaiste Runs als fehlgeschlagen darstellen (Spec 17, FR-17-05)
    const stale =
      !['completed', 'failed', 'cancelled'].includes(run.status) &&
      !isRunActive(run.id) &&
      Date.now() - new Date(run.updatedAt).getTime() > getConfig().RUN_STALE_AFTER_MS;

    const message = run.responseMessageId ? ctx.repos.messages.get(run.responseMessageId) : undefined;
    return NextResponse.json({
      run: stale
        ? { ...run, status: 'failed', error: run.error ?? { code: 'INTERNAL', userMessage: 'Der Run wurde unterbrochen.' } }
        : run,
      steps: ctx.repos.steps.listByRun(run.id),
      sources: ctx.repos.sources.listByRun(run.id),
      excerpts: ctx.repos.excerpts.listByRun(run.id),
      conflicts: ctx.repos.conflicts.listByRun(run.id),
      toolCalls: ctx.repos.toolCalls.listByRun(run.id),
      usage: ctx.repos.usage.listByRun(run.id),
      message: message ?? null,
      citations: message ? ctx.repos.citations.listByMessage(message.id) : [],
    });
  });
}

import { NextResponse } from 'next/server';
import { withApi, parseBody, notFound } from '@/lib/api/handler';
import { createRunRequestSchema } from '@/lib/contracts/schemas';
import { budgetsFor } from '@/lib/agent/paths';
import { executeRun } from '@/lib/agent/orchestrator';
import { logger } from '@/lib/util/logger';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function POST(request: Request) {
  return withApi(
    request,
    async (ctx) => {
      const body = await parseBody(request, createRunRequestSchema);
      const text = body.message.trim();
      if (text.length === 0) throw notFound('Nachricht');

      const conversation = body.conversationId
        ? ctx.repos.conversations.get(body.conversationId, ctx.userId)
        : ctx.repos.conversations.create(ctx.userId);
      if (!conversation) throw notFound('Conversation');

      const userMessage = ctx.repos.messages.create(conversation.id, 'user', text, 'complete');
      ctx.repos.conversations.touch(conversation.id);

      // Budgets vorläufig aus dem angeforderten Modus; der Router verfeinert den Task-Typ im Run.
      const provisionalType =
        body.mode === 'chat' ? 'knowledge_question' : body.mode === 'research' ? 'deep_research' : 'deep_research';
      const run = ctx.repos.runs.create({
        conversationId: conversation.id,
        userId: ctx.userId,
        requestMessageId: userMessage.id,
        taskType: provisionalType,
        budgets: budgetsFor(provisionalType, ctx.config),
        modelOverride: body.model ?? null,
      });

      // Ausführung asynchron starten (ADR-006)
      void executeRun({ runId: run.id, mode: body.mode ?? 'auto' }).catch((err: unknown) => {
        logger.error('run execution crashed', { module: 'api', runId: run.id, error: String(err).slice(0, 300) });
      });

      return NextResponse.json(
        { runId: run.id, conversationId: conversation.id, userMessageId: userMessage.id },
        { status: 202 },
      );
    },
    { rateLimitKey: 'runs' },
  );
}

