/** Iterative Recherche mit Lückenanalyse und Sättigungserkennung (Spec 25, Spec 16). */
import type { PlanStep, StepResult, StopReason } from '@/lib/contracts/domain';
import type { ResearchContext } from './engine';
import { researchStep } from './engine';
import { detectConflicts, type DetectedConflict } from './conflicts';
import { gapSteps } from '../planner';
import { topoSort } from '@/lib/util/graph';
import { mapLimit } from '@/lib/util/concurrency';
import { trustScoreFor, classifySource } from './source-scoring';
import { logger } from '@/lib/util/logger';
import { isAbort } from '@/lib/util/errors';

export interface LoopResult {
  iterations: number;
  stepResults: StepResult[];
  gaps: string[];
  conflicts: DetectedConflict[];
  stopReason: StopReason;
  plan: PlanStep[];
}

function evaluateGaps(
  plan: PlanStep[],
  results: Map<string, StepResult>,
  minSources: number,
  minConfidence: number,
): string[] {
  const gaps: string[] = [];
  const seen = new Set<string>();
  const add = (question: string) => {
    const key = question.trim().toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    gaps.push(question);
  };
  for (const step of plan) {
    const result = results.get(step.id);
    if (!result || result.items.length === 0) {
      add(step.question);
      continue;
    }
    const distinct = new Set(result.sourceIds).size;
    if (distinct < minSources || result.confidence < minConfidence) add(step.question);
  }
  return gaps;
}

export async function runResearchLoop(ctx: ResearchContext, initialPlan: PlanStep[]): Promise<LoopResult> {
  let plan = [...initialPlan];
  const results = new Map<string, StepResult>();
  let stopReason: StopReason = 'answered';
  let iterations = 0;

  for (;;) {
    if (ctx.state.checkCancellation()) { stopReason = 'cancelled'; break; }
    iterations++;
    ctx.state.nextIteration();

    const sourcesBefore = ctx.repos.sources.listByRun(ctx.runId).length;
    const claimsBefore = new Set(
      Array.from(results.values()).flatMap((r) => r.items.map((i) => i.claimKey)),
    ).size;

    const pending = plan.filter((s) => s.status === 'pending');
    const { ordered } = topoSort(pending);
    const done = new Set(
      plan.filter((s) => s.status === 'completed').map((s) => s.id),
    );

    // Wellen bilden: Schritte ohne offene Abhängigkeit laufen parallel (Spec 16, FR-16-02)
    let remaining = ordered;
    while (remaining.length > 0) {
      if (ctx.state.checkCancellation()) { stopReason = 'cancelled'; break; }
      const ready = remaining.filter((s) => s.dependsOn.every((d) => done.has(d)));
      const wave = ready.length > 0 ? ready : remaining.slice(0, 1);

      if (!ctx.state.hasBudgetForResearch()) {
        for (const step of remaining) {
          step.status = 'skipped';
          ctx.repos.steps.update(step.id, { status: 'skipped' });
        }
        stopReason = 'budget';
        remaining = [];
        break;
      }

      const waveResults = await mapLimit(wave, ctx.config.STEP_CONCURRENCY, async (step) => {
        step.status = 'running';
        ctx.repos.steps.update(step.id, { status: 'running' });
        try {
          const result = await researchStep(ctx, step);
          return { step, result };
        } catch (err) {
          if (isAbort(err)) throw err;
          logger.warn('step failed', { module: 'loop', runId: ctx.runId, stepId: step.id });
          return {
            step,
            result: {
              stepId: step.id, answer: '', sourceIds: [], items: [],
              confidence: 0, note: 'Schritt fehlgeschlagen',
            } as StepResult,
          };
        }
      });

      for (const { step, result } of waveResults) {
        results.set(step.id, result);
        step.status = result.items.length > 0 ? 'completed' : 'failed';
        step.result = result;
        ctx.repos.steps.update(step.id, { status: step.status, result });
        if (step.status === 'completed') done.add(step.id);
      }

      remaining = remaining.filter((s) => !wave.includes(s));
      // Schritte, deren Vorgänger endgültig fehlschlugen, überspringen (Spec 16, FR-16-04)
      const blocked = remaining.filter((s) =>
        s.dependsOn.some((d) => {
          const dep = plan.find((p) => p.id === d);
          return dep && (dep.status === 'failed' || dep.status === 'skipped');
        }),
      );
      for (const step of blocked) {
        step.status = 'skipped';
        ctx.repos.steps.update(step.id, { status: 'skipped' });
      }
      remaining = remaining.filter((s) => !blocked.includes(s));
    }

    if (stopReason === 'cancelled' || stopReason === 'budget') break;

    const gaps = evaluateGaps(plan, results, ctx.config.MIN_SOURCES_PER_CLAIM, ctx.config.MIN_STEP_CONFIDENCE);
    if (gaps.length === 0) { stopReason = 'answered'; break; }

    // Sättigung: diese Iteration brachte weder neue Quelle noch neuen claimKey (Spec 25, FR-25-04)
    const sourcesAfter = ctx.repos.sources.listByRun(ctx.runId).length;
    const claimsAfter = new Set(
      Array.from(results.values()).flatMap((r) => r.items.map((i) => i.claimKey)),
    ).size;
    if (iterations > 1 && sourcesAfter === sourcesBefore && claimsAfter === claimsBefore) {
      stopReason = 'saturation';
      break;
    }

    if (iterations >= ctx.state.budgets.maxIterations) { stopReason = 'budget'; break; }
    if (!ctx.state.hasBudgetForResearch()) { stopReason = 'budget'; break; }

    const followUps = gapSteps(gaps, plan.length + 1);
    if (followUps.length === 0) { stopReason = 'saturation'; break; }
    ctx.repos.steps.createMany(ctx.runId, followUps);
    plan = [...plan, ...followUps];
    ctx.emitter.emit('plan.updated', {
      reason: `${gaps.length} offene Punkte — Nachrecherche gestartet`,
      steps: followUps.map((s) => ({ id: s.id, title: s.title, question: s.question })),
    });
  }

  const allItems = Array.from(results.values()).flatMap((r) => r.items);
  const sources = ctx.repos.sources.listByRun(ctx.runId);
  const comparison = detectConflicts(allItems, sources, ctx.config.CONFLICT_NUMERIC_TOLERANCE);

  // Trust-Score um Übereinstimmung nachjustieren (Spec 26, FR-26-04)
  for (const source of sources) {
    if (source.status !== 'fetched') continue;
    const agreements = comparison.agreementBySource.get(source.id) ?? 0;
    const itemsOfSource = allItems.filter((i) => i.sourceId === source.id).length;
    const agreement = itemsOfSource > 0 ? Math.min(1, agreements / itemsOfSource) : 0;
    ctx.repos.sources.update(source.id, {
      trustScore: trustScoreFor({
        domain: source.domain,
        sourceType: source.sourceType || classifySource(source.domain),
        publishedAt: source.publishedAt,
        agreement,
      }),
    });
  }

  if (comparison.comparedCount > 0) {
    ctx.emitter.emit('sources.compared', {
      comparedCount: comparison.comparedCount,
      agreementCount: comparison.agreementCount,
      conflictCount: comparison.conflicts.length,
    });
  }
  for (const conflict of comparison.conflicts) {
    ctx.repos.conflicts.create(ctx.runId, conflict.claimKey, conflict.description, conflict.entries);
    ctx.emitter.emit('conflict.detected', {
      claimKey: conflict.claimKey,
      description: conflict.description.slice(0, 300),
      sourceIndexes: conflict.entries.map((e) => e.index),
    });
  }

  return {
    iterations,
    stepResults: Array.from(results.values()),
    gaps: evaluateGaps(plan, results, ctx.config.MIN_SOURCES_PER_CLAIM, ctx.config.MIN_STEP_CONFIDENCE),
    conflicts: comparison.conflicts,
    stopReason,
    plan,
  };
}

/** Quellentyp und Trust-Score (Spec 26, FR-26-04/05). */
import type { SourceType } from '@/lib/contracts/domain';

const SOCIAL = /(twitter|x\.com|facebook|instagram|tiktok|reddit|threads|linkedin)/i;
const AGGREGATOR = /(wikipedia|wikiwand|transfermarkt|statista|sportdaten|fandom|quora|pinterest)/i;
const NEWS = /(spiegel|zeit|faz|sueddeutsche|welt|kicker|bbc|guardian|reuters|nytimes|handelsblatt|heise|tagesschau|bundesliga|footballmoney)/i;
const OFFICIAL_TLD = /\.(gov|edu|org|int)$/i;
const OFFICIAL_HINT = /(fcbayern|uefa|fifa|dfb|europa\.eu|destatis|bundesbank|who|oecd|eurostat)/i;
const BLOG = /(medium\.com|blogspot|wordpress\.com|substack|tumblr)/i;

export function classifySource(domain: string): SourceType {
  if (SOCIAL.test(domain)) return 'social';
  if (OFFICIAL_TLD.test(domain) || OFFICIAL_HINT.test(domain)) return 'primary';
  if (AGGREGATOR.test(domain)) return 'aggregator';
  if (NEWS.test(domain)) return 'secondary';
  if (BLOG.test(domain)) return 'aggregator';
  return 'unknown';
}

const TYPE_SCORE: Record<SourceType, number> = {
  primary: 1, secondary: 0.7, aggregator: 0.5, social: 0.25, unknown: 0.4,
};

export function recencyScore(publishedAt: string | null, now = Date.now()): number {
  if (!publishedAt) return 0.3;
  const ts = new Date(publishedAt).getTime();
  if (Number.isNaN(ts)) return 0.3;
  const days = (now - ts) / 86_400_000;
  if (days <= 90) return 1;
  if (days <= 365) return 0.8;
  if (days <= 1095) return 0.5;
  return 0.3;
}

export function reputationScore(domain: string): number {
  if (OFFICIAL_HINT.test(domain)) return 0.9;
  if (OFFICIAL_TLD.test(domain)) return 0.8;
  if (NEWS.test(domain)) return 0.75;
  if (BLOG.test(domain)) return 0.4;
  if (AGGREGATOR.test(domain)) return 0.65;
  return 0.6;
}

export interface TrustInput {
  domain: string;
  sourceType: SourceType;
  publishedAt: string | null;
  /** Anteil bestätigter Werte (0..1). */
  agreement: number;
}

export function trustScoreFor(input: TrustInput): number {
  const score =
    0.35 * (TYPE_SCORE[input.sourceType] ?? 0.4) +
    0.25 * recencyScore(input.publishedAt) +
    0.25 * reputationScore(input.domain) +
    0.15 * Math.min(1, Math.max(0, input.agreement));
  return Math.round(score * 1000) / 1000;
}

/** Klassifikation der Anfrage (Spec 13). */
import type { LLMProvider } from '@/lib/llm/provider';
import type { AppConfig } from '@/lib/config/env';
import type { RouteDecision, RunMode, TaskType } from '@/lib/contracts/domain';
import { routerOutputSchema } from '@/lib/contracts/schemas';
import { routerPrompt } from './prompts';
import { PATHS, budgetsFor } from './paths';
import { logger } from '@/lib/util/logger';
import { isAbort } from '@/lib/util/errors';

const GREETING_ONLY = /^(hi|hallo|hey|moin|servus|yo|hello|guten (morgen|tag|abend)|danke|tschüss|bye)[\s!.,?]*$/i;

export function decisionFor(taskType: TaskType, confidence: number, summary: string, config: AppConfig, clarificationNeeded = false): RouteDecision {
  const path = PATHS[taskType];
  return {
    taskType,
    confidence,
    summary: summary.slice(0, 160),
    clarificationNeeded,
    allowedTools: path.allowedTools,
    showActivity: path.showActivity,
    needsResearch: path.needsResearch,
    budgets: budgetsFor(taskType, config),
  };
}

export async function route(args: {
  request: string;
  history: { role: 'user' | 'assistant'; text: string }[];
  mode: RunMode;
  llm: LLMProvider;
  config: AppConfig;
  signal?: AbortSignal;
  runId?: string;
}): Promise<RouteDecision> {
  const { request, mode, config } = args;

  if (mode === 'chat') {
    return decisionFor('knowledge_question', 1, 'Modus „Chat" vom Nutzer erzwungen', config);
  }
  if (mode === 'research') {
    return decisionFor('deep_research', 1, 'Modus „Recherche" vom Nutzer erzwungen', config);
  }
  if (GREETING_ONLY.test(request.trim())) {
    return decisionFor('conversation', 0.99, 'Begrüßung erkannt', config);
  }

  const history = args.history.slice(-6).map((m) => `${m.role}: ${m.text.slice(0, 200)}`);
  const prompt = routerPrompt(request, history);
  try {
    const output = await args.llm.generateObject({
      system: prompt.system,
      input: prompt.input,
      model: 'fast',
      schema: routerOutputSchema,
      schemaName: 'router_decision',
      purpose: 'router',
      ...(args.signal ? { signal: args.signal } : {}),
      ...(args.runId ? { runId: args.runId } : {}),
    });

    let taskType = output.taskType;
    let confidence = output.confidence;

    // Bei geringer Sicherheit den günstigeren Pfad wählen (FR-13-02)
    if (confidence < config.ROUTER_CONFIDENCE_THRESHOLD && PATHS[taskType].needsResearch) {
      taskType = taskType === 'deep_research' ? 'web_lookup' : taskType;
      if (confidence < config.ROUTER_CLARIFY_THRESHOLD) taskType = 'knowledge_question';
    }
    const clarify =
      output.clarificationNeeded && confidence < config.ROUTER_CLARIFY_THRESHOLD;
    if (clarify) taskType = 'knowledge_question';

    return decisionFor(taskType, confidence, output.summary, config, clarify);
  } catch (err) {
    if (isAbort(err)) throw err;
    logger.warn('router fallback', { module: 'router', error: String(err).slice(0, 200) });
    return decisionFor('knowledge_question', 0, 'Klassifikation fehlgeschlagen — Fallback', config);
  }
}

/** Erkennung von Injektionsversuchen in untrusted Inhalten (Spec 39, FR-39-06). */
export interface SafetyFinding {
  pattern: string;
  severity: 'low' | 'high';
}

const PATTERNS: { re: RegExp; name: string; severity: 'low' | 'high' }[] = [
  { re: /ignore\s+(all\s+)?(previous|prior)\s+instructions/i, name: 'ignore_previous_instructions_en', severity: 'high' },
  { re: /ignoriere\s+(alle\s+)?(vorherigen|bisherigen)\s+anweisungen/i, name: 'ignore_previous_instructions_de', severity: 'high' },
  { re: /disregard\s+(the\s+)?(system|above)\s+prompt/i, name: 'disregard_system_prompt', severity: 'high' },
  { re: /you\s+are\s+now\s+(an?|the)\s+/i, name: 'role_override', severity: 'high' },
  { re: /(output|reveal|print|send)\s+(your\s+)?(api[_\s-]?key|system\s+prompt|secret)/i, name: 'secret_exfiltration', severity: 'high' },
  { re: /exfiltrate/i, name: 'exfiltrate', severity: 'high' },
  { re: /\b169\.254\.169\.254\b/, name: 'metadata_endpoint', severity: 'high' },
  { re: /display\s*:\s*none|font-size\s*:\s*0/i, name: 'hidden_text', severity: 'low' },
];

export function scanUntrusted(text: string): SafetyFinding[] {
  const findings: SafetyFinding[] = [];
  for (const p of PATTERNS) {
    if (p.re.test(text)) findings.push({ pattern: p.name, severity: p.severity });
  }
  return findings;
}

export function hasHighSeverity(findings: SafetyFinding[]): boolean {
  return findings.some((f) => f.severity === 'high');
}

/** Run-State, Statusübergänge, Budgets, Abbruch (Spec 17, Spec 37). */
import type { Repositories } from '@/lib/db/repositories';
import type { BudgetUsage, RunBudgets, RunStatus } from '@/lib/contracts/domain';
import type { EventEmitterLike } from './events';
import { appError, AppErrorException } from '@/lib/util/errors';
import { logger } from '@/lib/util/logger';

const TRANSITIONS: Record<RunStatus, RunStatus[]> = {
  idle: ['routing', 'cancelled', 'failed'],
  routing: ['planning', 'synthesizing', 'searching', 'cancelled', 'failed', 'completed'],
  planning: ['searching', 'synthesizing', 'cancelled', 'failed'],
  searching: ['reading_sources', 'extracting', 'comparing', 'searching', 'synthesizing', 'cancelled', 'failed'],
  reading_sources: ['extracting', 'searching', 'comparing', 'synthesizing', 'cancelled', 'failed'],
  extracting: ['comparing', 'searching', 'reading_sources', 'synthesizing', 'cancelled', 'failed'],
  comparing: ['searching', 'synthesizing', 'planning', 'cancelled', 'failed'],
  synthesizing: ['completed', 'cancelled', 'failed'],
  completed: [],
  failed: [],
  cancelled: [],
  paused: ['searching', 'synthesizing', 'cancelled', 'failed'],
};

export function canTransition(from: RunStatus, to: RunStatus): boolean {
  return (TRANSITIONS[from] ?? []).includes(to);
}

export type BudgetKind = 'time' | 'cost' | 'tokens' | 'iterations' | 'searches' | 'sources';

export class RunStateManager {
  private status: RunStatus = 'idle';
  private readonly warned = new Set<BudgetKind>();
  readonly usage: BudgetUsage;
  readonly controller = new AbortController();

  constructor(
    readonly runId: string,
    readonly conversationId: string,
    readonly budgets: RunBudgets,
    readonly repos: Repositories,
    private readonly emitter: EventEmitterLike,
    usage?: BudgetUsage,
  ) {
    this.usage = usage ?? {
      iterations: 0, searches: 0, sources: 0, toolCalls: 0,
      inputTokens: 0, outputTokens: 0, costMicroUsd: 0,
      startedAt: new Date().toISOString(),
    };
  }

  private cancelWatcher: ReturnType<typeof setInterval> | undefined;

  get signal(): AbortSignal {
    return this.controller.signal;
  }

  /**
   * Abbruchwunsch wird zusätzlich persistent geprüft (ADR-011): Next.js kann Route-Handler in
   * getrennten Modulinstanzen ausführen, sodass die In-Process-Registry allein nicht genügt.
   */
  checkCancellation(): boolean {
    if (this.controller.signal.aborted) return true;
    try {
      if (this.repos.runs.isCancelRequested(this.runId)) {
        this.cancel();
        return true;
      }
    } catch {
      /* DB-Fehler dürfen den Run nicht beenden */
    }
    return false;
  }

  /** Startet die Hintergrundprüfung des Abbruchwunsches (z. B. während des Streamings). */
  startCancelWatch(intervalMs = 250): void {
    if (this.cancelWatcher) return;
    this.cancelWatcher = setInterval(() => {
      if (this.checkCancellation()) this.stopCancelWatch();
    }, intervalMs);
    this.cancelWatcher.unref?.();
  }

  stopCancelWatch(): void {
    if (this.cancelWatcher) {
      clearInterval(this.cancelWatcher);
      this.cancelWatcher = undefined;
    }
  }

  get currentStatus(): RunStatus {
    return this.status;
  }

  get elapsedMs(): number {
    return Date.now() - new Date(this.usage.startedAt).getTime();
  }

  setStatus(to: RunStatus): void {
    if (this.status === to) return;
    if (!canTransition(this.status, to)) {
      throw new AppErrorException(
        appError('INTERNAL', `unzulässiger Statuswechsel ${this.status} → ${to}`),
      );
    }
    const from = this.status;
    this.status = to;
    this.repos.runs.update(this.runId, { status: to });
    this.emitter.emit('status.changed', { from, to });
  }

  /** Erzwingt einen Endstatus auch aus inkonsistentem Zustand (nur für finally-Pfade). */
  forceStatus(to: RunStatus): void {
    const from = this.status;
    this.status = to;
    this.repos.runs.update(this.runId, { status: to });
    if (from !== to) this.emitter.emit('status.changed', { from, to });
  }

  cancel(): void {
    if (!this.controller.signal.aborted) this.controller.abort();
  }

  addUsage(patch: Partial<Pick<BudgetUsage, 'inputTokens' | 'outputTokens' | 'costMicroUsd'>>): void {
    this.usage.inputTokens += patch.inputTokens ?? 0;
    this.usage.outputTokens += patch.outputTokens ?? 0;
    this.usage.costMicroUsd += patch.costMicroUsd ?? 0;
    this.persistUsage();
    this.checkWarning('cost', this.usage.costMicroUsd, this.budgets.maxCostMicroUsd);
    this.checkWarning('tokens', this.usage.inputTokens, this.budgets.maxInputTokens);
  }

  consume(kind: 'search' | 'source' | 'toolCall'): void {
    if (kind === 'search') {
      if (this.usage.searches >= this.budgets.maxSearches) {
        throw new AppErrorException(appError('BUDGET_EXCEEDED', 'Suchbudget erschöpft'));
      }
      this.usage.searches++;
      this.checkWarning('searches', this.usage.searches, this.budgets.maxSearches);
    } else if (kind === 'source') {
      if (this.usage.sources >= this.budgets.maxSources) {
        throw new AppErrorException(appError('BUDGET_EXCEEDED', 'Quellenbudget erschöpft'));
      }
      this.usage.sources++;
      this.checkWarning('sources', this.usage.sources, this.budgets.maxSources);
    } else {
      if (this.usage.toolCalls >= this.budgets.maxToolCalls) {
        throw new AppErrorException(appError('BUDGET_EXCEEDED', 'Werkzeugbudget erschöpft'));
      }
      this.usage.toolCalls++;
    }
    this.persistUsage();
  }

  nextIteration(): void {
    this.usage.iterations++;
    this.checkWarning('iterations', this.usage.iterations, this.budgets.maxIterations);
    this.persistUsage();
  }

  /** true, wenn weitergearbeitet werden darf. Reserviert 20 % Zeit-/Kostenbudget für die Synthese. */
  hasBudgetForResearch(): boolean {
    if (this.checkCancellation()) return false;
    if (this.elapsedMs > this.budgets.maxWallClockMs * 0.8) {
      this.checkWarning('time', this.elapsedMs, this.budgets.maxWallClockMs);
      return false;
    }
    if (this.usage.costMicroUsd > this.budgets.maxCostMicroUsd * 0.8) return false;
    if (this.usage.searches >= this.budgets.maxSearches) return false;
    if (this.usage.sources >= this.budgets.maxSources) return false;
    if (this.usage.toolCalls >= this.budgets.maxToolCalls) return false;
    return true;
  }

  private checkWarning(kind: BudgetKind, used: number, limit: number): void {
    if (limit <= 0 || this.warned.has(kind)) return;
    if (used >= limit * 0.8) {
      this.warned.add(kind);
      this.emitter.emit('budget.warning', { kind, used: Math.round(used), limit });
    }
  }

  private persistUsage(): void {
    try {
      this.repos.runs.update(this.runId, { usage: this.usage });
    } catch (err) {
      logger.warn('usage persist failed', { module: 'state', runId: this.runId, error: String(err) });
    }
  }
}

/** Registry laufender Runs für den Abbruch aus dem API-Handler (Spec 17, FR-17-04). */
const registry = new Map<string, RunStateManager>();

export function registerRun(state: RunStateManager): void {
  registry.set(state.runId, state);
}

export function unregisterRun(runId: string): void {
  registry.delete(runId);
}

export function cancelRun(runId: string): boolean {
  const state = registry.get(runId);
  if (!state) return false;
  state.cancel();
  return true;
}

export function markCancelled(runId: string, repos: { runs: { requestCancel: (id: string) => void } }): void {
  repos.runs.requestCancel(runId);
  cancelRun(runId);
}

export function isRunActive(runId: string): boolean {
  return registry.has(runId);
}

/** Gemeinsame Hülle für alle Route Handler (Spec 08). */
import { NextResponse } from 'next/server';
import type { z } from 'zod';
import { getConfig } from '@/lib/config/env';
import { getRepositories, LOCAL_USER_ID, type Repositories } from '@/lib/db/repositories';
import { appError, AppErrorException, toAppError } from '@/lib/util/errors';
import type { AppError, ErrorCode } from '@/lib/contracts/errors';
import { checkRateLimit } from '@/lib/util/rate-limit';
import { logger } from '@/lib/util/logger';

const STATUS_BY_CODE: Partial<Record<ErrorCode, number>> = {
  VALIDATION_FAILED: 400,
  UNAUTHORIZED: 401,
  NOT_FOUND: 404,
  RATE_LIMITED: 429,
};

export interface ApiContext {
  repos: Repositories;
  userId: string;
  config: ReturnType<typeof getConfig>;
  origin: string;
}

export function errorResponse(error: AppError, status?: number): NextResponse {
  return NextResponse.json(
    { error: { code: error.code, message: error.message, userMessage: error.userMessage, retryable: error.retryable } },
    { status: status ?? STATUS_BY_CODE[error.code] ?? 500 },
  );
}

export function apiContext(request: Request): ApiContext {
  const repos = getRepositories();
  repos.users.ensureLocal();
  return {
    repos,
    userId: LOCAL_USER_ID,
    config: getConfig(),
    origin: new URL(request.url).origin,
  };
}

export async function withApi(
  request: Request,
  handler: (ctx: ApiContext) => Promise<NextResponse>,
  options: { rateLimitKey?: string; limit?: number } = {},
): Promise<NextResponse> {
  const started = Date.now();
  let status = 200;
  try {
    const ctx = apiContext(request);
    if (options.rateLimitKey && ctx.config.RATE_LIMIT_ENABLED) {
      const result = checkRateLimit(
        `${ctx.userId}:${options.rateLimitKey}`,
        options.limit ?? ctx.config.RATE_LIMIT_RUNS_PER_HOUR,
        3_600_000,
      );
      if (!result.allowed) {
        const error = appError('RATE_LIMITED', 'rate limit exceeded');
        status = 429;
        const response = errorResponse(error, 429);
        response.headers.set('Retry-After', String(Math.max(1, result.resetInSeconds)));
        return response;
      }
    }
    const response = await handler(ctx);
    status = response.status;
    return response;
  } catch (err) {
    const error = err instanceof AppErrorException ? err.appError : toAppError(err);
    status = STATUS_BY_CODE[error.code] ?? 500;
    if (status >= 500) {
      logger.error('api error', { module: 'api', code: error.code, message: error.message });
    }
    return errorResponse(error, status);
  } finally {
    logger.info('request', {
      module: 'api',
      method: request.method,
      path: new URL(request.url).pathname,
      status,
      ms: Date.now() - started,
    });
  }
}

export async function parseBody<T>(request: Request, schema: z.ZodType<T>): Promise<T> {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    throw new AppErrorException(appError('VALIDATION_FAILED', 'Body ist kein gültiges JSON'));
  }
  const parsed = schema.safeParse(json);
  if (!parsed.success) {
    const detail = parsed.error.issues.map((i) => `${i.path.join('.') || 'body'}: ${i.message}`).join('; ');
    throw new AppErrorException(appError('VALIDATION_FAILED', detail, { userMessage: detail }));
  }
  return parsed.data;
}

export function notFound(what = 'Eintrag'): AppErrorException {
  return new AppErrorException(appError('NOT_FOUND', `${what} nicht gefunden`));
}

export function conflict(message: string): AppErrorException {
  return new AppErrorException(
    appError('VALIDATION_FAILED', message, { userMessage: message }),
  );
}

/** Reine Abbildung der Eventfolge auf den Activity-State (Spec 30). */
import type { AgentEvent, EventType } from '@/lib/contracts/events';
import type { RunStatus } from '@/lib/contracts/domain';

export interface ActivityLine {
  id: string;
  kind: 'plan' | 'search' | 'source' | 'compare' | 'status' | 'warning' | 'error' | 'info';
  text: string;
  ts: string;
  count?: number;
}

export interface ActivityStep {
  id: string;
  title: string;
  question: string;
  status: 'pending' | 'running' | 'completed' | 'failed';
}

export interface ActivityState {
  status: RunStatus;
  visible: boolean;
  steps: ActivityStep[];
  lines: ActivityLine[];
  counters: { searches: number; sources: number; iterations: number; conflicts: number; citations: number };
  summary?: { durationMs: number; sourceCount: number; citationCount: number; costMicroUsd: number; stopReason: string };
  error?: string;
  messageId?: string;
  streamed: string;
  finished: boolean;
}

export const STATUS_TEXT: Record<RunStatus, string> = {
  idle: 'Bereit',
  routing: 'Anfrage wird analysiert …',
  planning: 'Recherche wird geplant …',
  searching: 'Suche läuft …',
  reading_sources: 'Quellen werden gelesen …',
  extracting: 'Informationen werden extrahiert …',
  comparing: 'Quellen werden verglichen …',
  synthesizing: 'Antwort wird erstellt …',
  completed: 'Recherche abgeschlossen',
  failed: 'Fehlgeschlagen',
  cancelled: 'Abgebrochen',
  paused: 'Pausiert',
};

export const initialActivityState: ActivityState = {
  status: 'idle',
  visible: false,
  steps: [],
  lines: [],
  counters: { searches: 0, sources: 0, iterations: 0, conflicts: 0, citations: 0 },
  streamed: '',
  finished: false,
};

const MAX_LINES = 200;

function push(state: ActivityState, line: Omit<ActivityLine, 'id'>): ActivityLine[] {
  const previous = state.lines[state.lines.length - 1];
  // Gleichartige Folgeereignisse zusammenfassen (Spec 30, Edge 1)
  if (previous && previous.kind === line.kind && previous.text === line.text) {
    const merged = { ...previous, count: (previous.count ?? 1) + 1 };
    return [...state.lines.slice(0, -1), merged];
  }
  const lines = [...state.lines, { ...line, id: `${state.lines.length}-${line.ts}` }];
  return lines.length > MAX_LINES ? lines.slice(lines.length - MAX_LINES) : lines;
}

export function activityReducer(state: ActivityState, event: AgentEvent): ActivityState {
  const ts = event.ts;
  switch (event.type as EventType) {
    case 'run.started':
      return { ...initialActivityState, status: 'routing', lines: push(state, { kind: 'info', text: 'Anfrage empfangen', ts }) };
    case 'router.classified': {
      const payload = event.payload as { taskType: string; confidence: number };
      const research = !['conversation', 'knowledge_question', 'unsafe_or_refused'].includes(payload.taskType);
      return {
        ...state,
        visible: research,
        lines: push(state, { kind: 'info', text: `Anfrage analysiert (${payload.taskType})`, ts }),
      };
    }
    case 'plan.created':
    case 'plan.updated': {
      const payload = event.payload as { steps: { id: string; title: string; question: string }[]; reason?: string };
      const steps: ActivityStep[] = payload.steps.map((s) => ({ ...s, status: 'pending' as const }));
      const existing = new Map(state.steps.map((s) => [s.id, s]));
      for (const step of steps) if (!existing.has(step.id)) existing.set(step.id, step);
      return {
        ...state,
        visible: true,
        steps: Array.from(existing.values()),
        counters: event.type === 'plan.updated'
          ? { ...state.counters, iterations: state.counters.iterations + 1 }
          : state.counters,
        lines: push(state, {
          kind: 'plan',
          text: payload.reason ?? `Recherche geplant (${payload.steps.length} Teilfragen)`,
          ts,
        }),
      };
    }
    case 'step.started': {
      const payload = event.payload as { stepId: string; title: string };
      return {
        ...state,
        steps: state.steps.map((s) => (s.id === payload.stepId ? { ...s, status: 'running' } : s)),
      };
    }
    case 'step.completed': {
      const payload = event.payload as { stepId: string; summary: string; status: string };
      return {
        ...state,
        steps: state.steps.map((s) =>
          s.id === payload.stepId ? { ...s, status: payload.status === 'completed' ? 'completed' : 'failed' } : s,
        ),
        lines: push(state, { kind: 'info', text: payload.summary, ts }),
      };
    }
    case 'search.results': {
      const payload = event.payload as { query: string; count: number };
      return {
        ...state,
        visible: true,
        counters: { ...state.counters, searches: state.counters.searches + 1 },
        lines: push(state, { kind: 'search', text: `Suche: „${payload.query}" — ${payload.count} Treffer`, ts }),
      };
    }
    case 'source.opened': {
      const payload = event.payload as { domain: string; index: number };
      return {
        ...state,
        counters: { ...state.counters, sources: state.counters.sources + 1 },
        lines: push(state, { kind: 'source', text: `Quelle ${payload.index} geöffnet: ${payload.domain}`, ts }),
      };
    }
    case 'source.extracted': {
      const payload = event.payload as { index: number; excerptCount: number };
      return {
        ...state,
        lines: push(state, {
          kind: 'source',
          text: `Quelle ${payload.index}: ${payload.excerptCount} Angaben extrahiert`,
          ts,
        }),
      };
    }
    case 'sources.compared': {
      const payload = event.payload as { comparedCount: number; conflictCount: number };
      return {
        ...state,
        lines: push(state, {
          kind: 'compare',
          text: `${payload.comparedCount} Angaben verglichen — ${payload.conflictCount} Abweichung(en)`,
          ts,
        }),
      };
    }
    case 'conflict.detected': {
      const payload = event.payload as { description: string };
      return {
        ...state,
        counters: { ...state.counters, conflicts: state.counters.conflicts + 1 },
        lines: push(state, { kind: 'warning', text: `Abweichung: ${payload.description}`, ts }),
      };
    }
    case 'safety.flagged': {
      const payload = event.payload as { sourceId: string; severity: string };
      return {
        ...state,
        lines: push(state, {
          kind: 'warning',
          text: `Verdächtiger Inhalt in einer Quelle ignoriert (${payload.severity})`,
          ts,
        }),
      };
    }
    case 'status.changed': {
      const payload = event.payload as { to: RunStatus };
      return { ...state, status: payload.to };
    }
    case 'message.delta': {
      const payload = event.payload as { messageId: string; delta: string };
      return { ...state, messageId: payload.messageId, streamed: state.streamed + payload.delta };
    }
    case 'citation.added':
      return { ...state, counters: { ...state.counters, citations: state.counters.citations + 1 } };
    case 'budget.warning': {
      const payload = event.payload as { kind: string; used: number; limit: number };
      return {
        ...state,
        lines: push(state, { kind: 'warning', text: `Budgetgrenze erreicht (${payload.kind})`, ts }),
      };
    }
    case 'tool.call.failed': {
      const payload = event.payload as { tool: string; message: string };
      return {
        ...state,
        lines: push(state, { kind: 'error', text: `${payload.tool}: ${payload.message}`, ts }),
      };
    }
    case 'run.completed': {
      const payload = event.payload as {
        messageId: string; sourceCount: number; citationCount: number;
        durationMs: number; costMicroUsd: number; stopReason: string;
      };
      return {
        ...state,
        status: 'completed',
        finished: true,
        messageId: payload.messageId,
        summary: {
          durationMs: payload.durationMs,
          sourceCount: payload.sourceCount,
          citationCount: payload.citationCount,
          costMicroUsd: payload.costMicroUsd,
          stopReason: payload.stopReason,
        },
        lines: push(state, { kind: 'status', text: 'Recherche abgeschlossen', ts }),
      };
    }
    case 'run.failed': {
      const payload = event.payload as { userMessage: string };
      return {
        ...state,
        status: 'failed',
        finished: true,
        error: payload.userMessage,
        lines: push(state, { kind: 'error', text: payload.userMessage, ts }),
      };
    }
    case 'run.cancelled':
      return {
        ...state,
        status: 'cancelled',
        finished: true,
        lines: push(state, { kind: 'status', text: 'Abgebrochen', ts }),
      };
    default:
      return state;
  }
}

export function replayEvents(events: AgentEvent[]): ActivityState {
  return events.reduce(activityReducer, initialActivityState);
}

/** Typisierte Client-Aufrufe gegen die API (Spec 08). */
import type { ConversationDetail, ConversationSummary, Mode } from './types';
import type { AgentEvent } from '@/lib/contracts/events';
import type { Citation, Conflict, Message, RunStatus, SourceRecord, ExcerptRecord } from '@/lib/contracts/domain';

async function request<T>(input: string, init?: RequestInit): Promise<T> {
  const response = await fetch(input, {
    ...init,
    headers: { 'Content-Type': 'application/json', ...(init?.headers ?? {}) },
  });
  if (!response.ok) {
    let message = `Fehler ${response.status}`;
    try {
      const body = (await response.json()) as { error?: { userMessage?: string } };
      if (body.error?.userMessage) message = body.error.userMessage;
    } catch {
      /* kein JSON-Body */
    }
    throw new Error(message);
  }
  if (response.status === 204) return undefined as T;
  return (await response.json()) as T;
}

export const api = {
  listConversations: () => request<{ conversations: ConversationSummary[] }>('/api/conversations'),
  getConversation: (id: string) => request<ConversationDetail>(`/api/conversations/${id}`),
  renameConversation: (id: string, title: string) =>
    request<unknown>(`/api/conversations/${id}`, { method: 'PATCH', body: JSON.stringify({ title }) }),
  deleteConversation: (id: string) => request<void>(`/api/conversations/${id}`, { method: 'DELETE' }),
  listModels: () =>
    request<{
      provider: string;
      models: { id: string; recommended: boolean; note?: string }[];
      currentFast: string | null;
      currentMain: string | null;
    }>('/api/models'),
  createRun: (message: string, conversationId: string | null, mode: Mode, model?: string) =>
    request<{ runId: string; conversationId: string; userMessageId: string }>('/api/runs', {
      method: 'POST',
      body: JSON.stringify({
        message, mode,
        ...(conversationId ? { conversationId } : {}),
        ...(model ? { model } : {}),
      }),
    }),
  cancelRun: (runId: string) => request<unknown>(`/api/runs/${runId}/cancel`, { method: 'POST' }),
  getRun: (runId: string) =>
    request<{
      run: { id: string; status: RunStatus; error: { userMessage: string } | null };
      sources: SourceRecord[];
      excerpts: ExcerptRecord[];
      conflicts: Conflict[];
      message: Message | null;
      citations: Citation[];
    }>(`/api/runs/${runId}`),
};

export type StreamHandlers = {
  onEvent: (event: AgentEvent) => void;
  onDone: () => void;
  onError: (message: string) => void;
};

export function openRunStream(runId: string, afterSeq: number, handlers: StreamHandlers): () => void {
  const source = new EventSource(`/api/runs/${runId}/events?after=${afterSeq}`);
  let finished = false;

  const handle = (raw: MessageEvent<string>) => {
    try {
      const event = JSON.parse(raw.data) as AgentEvent;
      handlers.onEvent(event);
      if (event.type === 'run.completed' || event.type === 'run.failed' || event.type === 'run.cancelled') {
        finished = true;
        source.close();
        handlers.onDone();
      }
    } catch {
      /* fehlerhaftes Event ignorieren */
    }
  };

  source.addEventListener('message', handle as EventListener);
  for (const type of [
    'run.started', 'router.classified', 'plan.created', 'plan.updated', 'step.started', 'step.completed',
    'tool.call.started', 'tool.call.completed', 'tool.call.failed', 'search.results', 'source.opened',
    'source.extracted', 'sources.compared', 'conflict.detected', 'status.changed', 'message.delta',
    'citation.added', 'budget.warning', 'safety.flagged', 'run.failed', 'run.cancelled', 'run.completed',
  ]) {
    source.addEventListener(type, handle as EventListener);
  }

  source.addEventListener('error', () => {
    if (finished) return;
    if (source.readyState === EventSource.CLOSED) {
      handlers.onError('Verbindung zum Agenten unterbrochen.');
    }
  });

  return () => {
    finished = true;
    source.close();
  };
}

