/** Reale Suchanbieter (Spec 19, FR-19-02). */
import OpenAI from 'openai';
import { z } from 'zod';
import type { SearchOptions, SearchProvider } from './provider';
import type { SearchHit } from '@/lib/contracts/domain';
import { getConfig } from '@/lib/config/env';
import { searchProviderInstruction } from '@/lib/agent/prompts';
import { appError, AppErrorException } from '@/lib/util/errors';

const hitsSchema = z.object({
  results: z.array(
    z.object({
      title: z.string(),
      url: z.string(),
      snippet: z.string(),
      publishedAt: z.string().optional(),
    }),
  ),
});

/** Nutzt das gehostete Web-Search-Tool der Responses API als reinen Trefferlieferanten. */
export class OpenAISearchProvider implements SearchProvider {
  readonly name = 'openai';
  private readonly client: OpenAI;

  constructor() {
    const config = getConfig();
    this.client = new OpenAI({ apiKey: config.OPENAI_API_KEY ?? '', maxRetries: 1 });
  }

  async search(query: string, opts: SearchOptions): Promise<SearchHit[]> {
    const config = getConfig();
    try {
      const response = await this.client.responses.create(
        {
          model: config.OPENAI_MODEL_FAST,
          instructions: searchProviderInstruction,
          input: `Suche: ${query}\nGib bis zu ${opts.maxResults} relevante Ergebnisse zurück.`,
          tools: [{ type: 'web_search' }],
          text: {
            format: {
              type: 'json_schema',
              name: 'search_results',
              strict: true,
              schema: {
                type: 'object',
                additionalProperties: false,
                required: ['results'],
                properties: {
                  results: {
                    type: 'array',
                    items: {
                      type: 'object',
                      additionalProperties: false,
                      required: ['title', 'url', 'snippet', 'publishedAt'],
                      properties: {
                        title: { type: 'string' },
                        url: { type: 'string' },
                        snippet: { type: 'string' },
                        publishedAt: { type: 'string' },
                      },
                    },
                  },
                },
              },
            },
          },
        } as never,
        { signal: opts.signal as AbortSignal | undefined },
      );
      const parsed = hitsSchema.safeParse(JSON.parse(response.output_text ?? '{"results":[]}'));
      if (!parsed.success) throw new Error(parsed.error.message);
      return parsed.data.results.slice(0, opts.maxResults).map((r, i) => ({
        title: r.title,
        url: r.url,
        snippet: r.snippet,
        ...(r.publishedAt ? { publishedAt: r.publishedAt } : {}),
        rank: i + 1,
      }));
    } catch (err) {
      throw new AppErrorException(
        appError('SEARCH_FAILED', `openai search failed: ${(err as Error).message.slice(0, 200)}`),
      );
    }
  }
}

export class BraveSearchProvider implements SearchProvider {
  readonly name = 'brave';

  async search(query: string, opts: SearchOptions): Promise<SearchHit[]> {
    const config = getConfig();
    const url = new URL(`${config.BRAVE_BASE_URL.replace(/\/$/, '')}/web/search`);
    url.searchParams.set('q', query);
    url.searchParams.set('count', String(opts.maxResults));
    try {
      const res = await fetch(url, {
        headers: {
          Accept: 'application/json',
          'X-Subscription-Token': config.BRAVE_API_KEY ?? '',
        },
        ...(opts.signal ? { signal: opts.signal } : {}),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = (await res.json()) as { web?: { results?: { title?: string; url?: string; description?: string; age?: string }[] } };
      return (data.web?.results ?? []).slice(0, opts.maxResults).map((r, i) => ({
        title: r.title ?? new URL(r.url ?? 'https://unknown.invalid').hostname,
        url: r.url ?? '',
        snippet: r.description ?? '',
        ...(r.age ? { publishedAt: r.age } : {}),
        rank: i + 1,
      })).filter((h) => h.url.length > 0);
    } catch (err) {
      throw new AppErrorException(
        appError('SEARCH_FAILED', `brave search failed: ${(err as Error).message.slice(0, 200)}`),
      );
    }
  }
}

export class TavilySearchProvider implements SearchProvider {
  readonly name = 'tavily';

  async search(query: string, opts: SearchOptions): Promise<SearchHit[]> {
    const config = getConfig();
    try {
      const res = await fetch(`${config.TAVILY_BASE_URL.replace(/\/$/, '')}/search`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          api_key: config.TAVILY_API_KEY ?? '',
          query,
          max_results: opts.maxResults,
        }),
        ...(opts.signal ? { signal: opts.signal } : {}),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = (await res.json()) as { results?: { title?: string; url?: string; content?: string; published_date?: string }[] };
      return (data.results ?? []).slice(0, opts.maxResults).map((r, i) => ({
        title: r.title ?? 'Ohne Titel',
        url: r.url ?? '',
        snippet: r.content ?? '',
        ...(r.published_date ? { publishedAt: r.published_date } : {}),
        rank: i + 1,
      })).filter((h) => h.url.length > 0);
    } catch (err) {
      throw new AppErrorException(
        appError('SEARCH_FAILED', `tavily search failed: ${(err as Error).message.slice(0, 200)}`),
      );
    }
  }
}

/** Sicherer Ausdrucksparser (Shunting-Yard) ohne dynamische Codeausführung (Spec 21, FR-21-02). */
export type CalcResult = { ok: true; value: number } | { ok: false; error: string };

type Token = { type: 'num'; value: number } | { type: 'op'; value: string } | { type: 'paren'; value: '(' | ')' };

const PRECEDENCE: Record<string, number> = { '+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '^': 3 };
const RIGHT_ASSOC = new Set(['^']);

function tokenize(input: string): Token[] | undefined {
  const tokens: Token[] = [];
  const normalized = input
    .replace(/×/g, '*').replace(/÷/g, '/').replace(/−/g, '-').replace(/\s+/g, '');
  let i = 0;
  while (i < normalized.length) {
    const char = normalized[i] as string;
    if (/[0-9.]/.test(char)) {
      let num = '';
      while (i < normalized.length && /[0-9.]/.test(normalized[i] as string)) {
        num += normalized[i];
        i++;
      }
      const value = Number(num);
      if (!Number.isFinite(value)) return undefined;
      tokens.push({ type: 'num', value });
      continue;
    }
    if (char in PRECEDENCE) {
      const previous = tokens[tokens.length - 1];
      const isUnary = char === '-' && (!previous || previous.type === 'op' || (previous.type === 'paren' && previous.value === '('));
      if (isUnary) {
        tokens.push({ type: 'num', value: 0 });
      }
      tokens.push({ type: 'op', value: char });
      i++;
      continue;
    }
    if (char === '(' || char === ')') {
      tokens.push({ type: 'paren', value: char });
      i++;
      continue;
    }
    return undefined; // nicht erlaubtes Zeichen
  }
  return tokens;
}

export function calculate(expression: string): CalcResult {
  if (expression.length > 200) return { ok: false, error: 'Ausdruck ist zu lang (max. 200 Zeichen)' };
  const tokens = tokenize(expression);
  if (!tokens || tokens.length === 0) return { ok: false, error: 'Ausdruck enthält unzulässige Zeichen' };

  const output: Token[] = [];
  const ops: Token[] = [];
  for (const token of tokens) {
    if (token.type === 'num') output.push(token);
    else if (token.type === 'op') {
      while (ops.length > 0) {
        const top = ops[ops.length - 1] as Token;
        if (top.type !== 'op') break;
        const topPrec = PRECEDENCE[top.value] ?? 0;
        const curPrec = PRECEDENCE[token.value] ?? 0;
        if (topPrec > curPrec || (topPrec === curPrec && !RIGHT_ASSOC.has(token.value))) {
          output.push(ops.pop() as Token);
        } else break;
      }
      ops.push(token);
    } else if (token.value === '(') ops.push(token);
    else {
      let found = false;
      while (ops.length > 0) {
        const top = ops.pop() as Token;
        if (top.type === 'paren' && top.value === '(') { found = true; break; }
        output.push(top);
      }
      if (!found) return { ok: false, error: 'Klammern sind unausgeglichen' };
    }
  }
  while (ops.length > 0) {
    const top = ops.pop() as Token;
    if (top.type === 'paren') return { ok: false, error: 'Klammern sind unausgeglichen' };
    output.push(top);
  }

  const stack: number[] = [];
  for (const token of output) {
    if (token.type === 'num') { stack.push(token.value); continue; }
    if (token.type !== 'op') return { ok: false, error: 'Ungültiger Ausdruck' };
    const b = stack.pop();
    const a = stack.pop();
    if (a === undefined || b === undefined) return { ok: false, error: 'Ungültiger Ausdruck' };
    switch (token.value) {
      case '+': stack.push(a + b); break;
      case '-': stack.push(a - b); break;
      case '*': stack.push(a * b); break;
      case '/':
        if (b === 0) return { ok: false, error: 'Division durch null' };
        stack.push(a / b);
        break;
      case '%':
        if (b === 0) return { ok: false, error: 'Division durch null' };
        stack.push(a % b);
        break;
      case '^': stack.push(Math.pow(a, b)); break;
      default: return { ok: false, error: 'Unbekannter Operator' };
    }
  }
  const value = stack.pop();
  if (value === undefined || stack.length > 0 || !Number.isFinite(value)) {
    return { ok: false, error: 'Ungültiger Ausdruck' };
  }
  return { ok: true, value };
}

export function formatNumber(value: number): string {
  if (Math.abs(value) >= 1e15 || (value !== 0 && Math.abs(value) < 1e-6)) return value.toExponential(6);
  return Number(value.toPrecision(15)).toLocaleString('de-DE', { maximumFractionDigits: 10 });
}

/** Sicherer Seitenabruf mit Guard, Größen- und Zeitlimit (Spec 20, Spec 39). */
import { getConfig } from '@/lib/config/env';
import { assertUrlAllowed, domainOf } from '@/lib/util/url-safety';
import { appError, AppErrorException } from '@/lib/util/errors';
import { withDomainLimit } from '@/lib/util/rate-limit';
import { extractContent, type ExtractedPage } from '@/lib/util/html';

const ALLOWED_TYPES = ['text/html', 'text/plain', 'application/xhtml+xml'];

export interface FetchedPage extends ExtractedPage {
  url: string;
  finalUrl: string;
  domain: string;
  fetchedAt: string;
}

const robotsCache = new Map<string, { at: number; disallow: string[] }>();
const ROBOTS_TTL_MS = 600_000;

async function robotsDisallows(origin: string, path: string, allowLoopback: boolean): Promise<boolean> {
  const config = getConfig();
  if (!config.RESPECT_ROBOTS) return false;
  const cached = robotsCache.get(origin);
  let disallow: string[];
  if (cached && Date.now() - cached.at < ROBOTS_TTL_MS) {
    disallow = cached.disallow;
  } else {
    disallow = [];
    try {
      const robotsUrl = `${origin}/robots.txt`;
      await assertUrlAllowed(robotsUrl, { allowLoopback });
      const res = await fetch(robotsUrl, {
        headers: { 'User-Agent': config.FETCH_USER_AGENT },
        signal: AbortSignal.timeout(3000),
      });
      if (res.ok) {
        const text = (await res.text()).slice(0, 100_000);
        let applies = false;
        for (const line of text.split('\n')) {
          const trimmed = line.trim();
          const ua = /^user-agent:\s*(.+)$/i.exec(trimmed);
          if (ua) { applies = (ua[1] ?? '').trim() === '*'; continue; }
          const rule = /^disallow:\s*(.*)$/i.exec(trimmed);
          if (rule && applies && (rule[1] ?? '').trim().length > 0) disallow.push((rule[1] as string).trim());
        }
      }
    } catch {
      /* robots.txt nicht erreichbar → Abruf erlaubt */
    }
    robotsCache.set(origin, { at: Date.now(), disallow });
  }
  return disallow.some((rule) => path.startsWith(rule));
}

export function clearRobotsCache(): void {
  robotsCache.clear();
}

export async function fetchPage(rawUrl: string, signal?: AbortSignal): Promise<FetchedPage> {
  const config = getConfig();
  const allowLoopback = config.ALLOW_LOOPBACK_FETCH;
  let current = rawUrl;
  let response: Response | undefined;

  for (let hop = 0; hop <= 3; hop++) {
    const url = await assertUrlAllowed(current, { allowLoopback });
    if (await robotsDisallows(url.origin, url.pathname, allowLoopback)) {
      throw new AppErrorException(appError('FETCH_BLOCKED', `robots.txt verbietet ${url.pathname}`));
    }
    const timeout = AbortSignal.timeout(config.FETCH_TIMEOUT_MS);
    const combined = signal ? AbortSignal.any([signal, timeout]) : timeout;
    const res = await withDomainLimit(url.hostname, config.DOMAIN_RATE_LIMIT_MS, () =>
      fetch(url, {
        redirect: 'manual',
        headers: {
          'User-Agent': config.FETCH_USER_AGENT,
          Accept: 'text/html,application/xhtml+xml,text/plain;q=0.9',
          'Accept-Language': 'de,en;q=0.8',
        },
        signal: combined,
      }).catch((err: Error) => {
        if (signal?.aborted) throw new AppErrorException(appError('RUN_CANCELLED', 'aborted'));
        throw new AppErrorException(appError('FETCH_FAILED', `${err.name}: ${err.message.slice(0, 120)}`));
      }),
      signal,
    );
    if (res.status >= 300 && res.status < 400) {
      const location = res.headers.get('location');
      if (!location) {
        throw new AppErrorException(appError('FETCH_FAILED', `Weiterleitung ohne Ziel (${res.status})`));
      }
      current = new URL(location, current).toString();
      continue;
    }
    response = res;
    break;
  }

  if (!response) throw new AppErrorException(appError('FETCH_FAILED', 'zu viele Weiterleitungen'));
  if (!response.ok) {
    throw new AppErrorException(appError('FETCH_FAILED', `HTTP ${response.status}`));
  }

  const contentType = (response.headers.get('content-type') ?? '').toLowerCase();
  if (!ALLOWED_TYPES.some((t) => contentType.includes(t))) {
    const hint = contentType.includes('pdf') ? 'PDF wird noch nicht unterstützt' : `Inhaltstyp ${contentType || 'unbekannt'} wird nicht verarbeitet`;
    throw new AppErrorException(appError('FETCH_BLOCKED', hint));
  }

  const declared = Number(response.headers.get('content-length') ?? 0);
  if (declared > config.FETCH_MAX_BYTES) {
    throw new AppErrorException(appError('CONTENT_TOO_LARGE', `${declared} Bytes > Limit`));
  }

  const html = await readLimited(response, config.FETCH_MAX_BYTES);
  const extracted = extractContent(html, current);
  return {
    ...extracted,
    url: rawUrl,
    finalUrl: current,
    domain: domainOf(current),
    fetchedAt: new Date().toISOString(),
  };
}

async function readLimited(response: Response, maxBytes: number): Promise<string> {
  const body = response.body;
  if (!body) return '';
  const reader = body.getReader();
  const decoder = new TextDecoder('utf-8');
  let total = 0;
  let text = '';
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > maxBytes) {
      await reader.cancel();
      throw new AppErrorException(appError('CONTENT_TOO_LARGE', `> ${maxBytes} Bytes`));
    }
    text += decoder.decode(value, { stream: true });
  }
  text += decoder.decode();
  return text;
}

/** Registry und Executor mit Guards, Timeout, Retry, Cache (Spec 18). */
import type { ToolName } from '@/lib/contracts/domain';
import type { ToolContext, ToolDefinition, ToolOutcome } from './types';
import { calculatorTool, datetimeTool } from './utilities';
import { extractContentTool, openUrlTool, searchInPageTool, webSearchTool } from './web';
import { toStrictJsonSchema, type JsonSchema } from '@/lib/contracts/json-schema';
import { appError, toAppError, withRetry } from '@/lib/util/errors';
import { truncateToTokens } from '@/lib/util/tokens';

const ALL_TOOLS: ToolDefinition<never, never>[] = [
  webSearchTool, openUrlTool, extractContentTool, searchInPageTool, calculatorTool, datetimeTool,
] as unknown as ToolDefinition<never, never>[];

const BY_NAME = new Map<ToolName, ToolDefinition<never, never>>(
  ALL_TOOLS.map((t) => [t.name, t]),
);

export function getTool(name: ToolName): ToolDefinition<never, never> | undefined {
  return BY_NAME.get(name);
}

export function getToolsFor(allowed: readonly ToolName[]): ToolDefinition<never, never>[] {
  return ALL_TOOLS.filter((t) => allowed.includes(t.name));
}

export interface ToolSchemaForModel {
  name: ToolName;
  description: string;
  parameters: JsonSchema;
}

export function toolSchemas(allowed: readonly ToolName[]): ToolSchemaForModel[] {
  return getToolsFor(allowed).map((t) => ({
    name: t.name,
    description: t.description,
    parameters: toStrictJsonSchema(t.parameters as never),
  }));
}

function stableKey(name: string, args: unknown): string {
  return `${name}:${JSON.stringify(args, Object.keys(args as object).sort())}`;
}

function argsSummary(args: Record<string, unknown>): string {
  const parts: string[] = [];
  for (const [key, value] of Object.entries(args)) {
    if (typeof value === 'string') parts.push(`${key}=${value.slice(0, 80)}`);
    else parts.push(`${key}=${JSON.stringify(value)?.slice(0, 40)}`);
  }
  return parts.join(' ').slice(0, 160);
}

export async function executeTool(
  name: ToolName,
  rawArgs: unknown,
  ctx: ToolContext,
  allowed: readonly ToolName[],
): Promise<ToolOutcome<unknown>> {
  if (!allowed.includes(name)) {
    return { ok: false, code: 'TOOL_FAILED', message: `Werkzeug ${name} ist für diese Aufgabe nicht verfügbar.` };
  }
  const tool = BY_NAME.get(name);
  if (!tool) {
    return { ok: false, code: 'TOOL_FAILED', message: `Unbekanntes Werkzeug: ${name}` };
  }
  return executeToolDefinition(tool, rawArgs, ctx);
}

/** Führt eine Tool-Definition mit allen Guards aus (direkt testbar). */
export async function executeToolDefinition(
  tool: ToolDefinition<never, never>,
  rawArgs: unknown,
  ctx: ToolContext,
): Promise<ToolOutcome<unknown>> {
  const name = tool.name;
  if (ctx.signal.aborted) {
    return { ok: false, code: 'RUN_CANCELLED', message: 'Der Lauf wurde abgebrochen.' };
  }
  const parsed = tool.parameters.safeParse(rawArgs);
  if (!parsed.success) {
    return {
      ok: false,
      code: 'VALIDATION_FAILED',
      message: `Ungültige Parameter für ${name}: ${parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; ')}`,
    };
  }
  const args = parsed.data as Record<string, unknown>;

  const cacheKey = stableKey(name, args);
  if (tool.cacheable && ctx.cache.has(cacheKey)) {
    return { ok: true, result: ctx.cache.get(cacheKey) };
  }

  try {
    ctx.consume('toolCall');
  } catch (err) {
    const e = toAppError(err);
    return { ok: false, code: e.code, message: e.userMessage };
  }

  const toolCallId = ctx.repos.toolCalls.start(ctx.runId, ctx.stepId, name, args);
  ctx.emitter.emit('tool.call.started', { toolCallId, tool: name, argsSummary: argsSummary(args) });
  const started = Date.now();

  try {
    const result = await withRetry(
      async () => {
        const timeout = AbortSignal.timeout(tool.timeoutMs);
        const signal = AbortSignal.any([ctx.signal, timeout]);
        const scoped: ToolContext = { ...ctx, signal };
        const value = await Promise.race([
          tool.execute(args as never, scoped),
          new Promise((_resolve, reject) => {
            timeout.addEventListener('abort', () => {
              reject(new Error('tool timeout'));
            }, { once: true });
          }) as Promise<never>,
        ]);
        const validated = tool.result.safeParse(value);
        if (!validated.success) {
          throw new Error(`Tool-Ergebnis ungültig: ${validated.error.message.slice(0, 160)}`);
        }
        return validated.data;
      },
      {
        maxAttempts: tool.maxRetries,
        baseMs: 250,
        signal: ctx.signal,
      },
    );

    const durationMs = Date.now() - started;
    const summary = tool.summarize(result as never);
    ctx.repos.toolCalls.finish(toolCallId, { status: 'completed', resultSummary: summary, durationMs });
    ctx.emitter.emit('tool.call.completed', { toolCallId, tool: name, durationMs, resultSummary: summary });
    if (tool.cacheable) ctx.cache.set(cacheKey, result);
    return { ok: true, result };
  } catch (err) {
    const durationMs = Date.now() - started;
    const isTimeout = err instanceof Error && err.message === 'tool timeout';
    const e = isTimeout ? appError('TOOL_TIMEOUT', `${name} timeout`) : toAppError(err);
    ctx.repos.toolCalls.finish(toolCallId, { status: 'failed', errorCode: e.code, durationMs });
    ctx.emitter.emit('tool.call.failed', {
      toolCallId, tool: name, code: e.code, message: e.userMessage.slice(0, 200),
    });
    return { ok: false, code: e.code, message: e.userMessage };
  }
}

/** Bereitet ein Tool-Ergebnis für das Modellkontextfenster auf (Spec 18, FR-18-05). */
export function toolResultForModel(name: ToolName, outcome: ToolOutcome<unknown>): string {
  const tool = BY_NAME.get(name);
  const budget = tool?.resultTokenBudget ?? 1000;
  if (!outcome.ok) {
    return JSON.stringify({ ok: false, code: outcome.code, message: outcome.message });
  }
  const { text } = truncateToTokens(JSON.stringify({ ok: true, result: outcome.result }), budget);
  return text;
}

