    expect(repos.toolCalls.listByRun(run.id)).toHaveLength(0);
  });

  it('AC-18-05: identische Aufrufe werden aus dem Cache bedient', async () => {
    const { ctx, repos, run } = setup();
    await executeTool('calculator', { expression: '2+2' }, ctx, ['calculator']);
    await executeTool('calculator', { expression: '2+2' }, ctx, ['calculator']);
    expect(repos.toolCalls.listByRun(run.id)).toHaveLength(1);
  });

  it('protokolliert erfolgreiche Aufrufe mit Events', async () => {
    const { ctx, repos, run } = setup();
    const outcome = await executeTool('calculator', { expression: '(1200+300)*0.19' }, ctx, ['calculator']);
    expect(outcome.ok).toBe(true);
    const events = repos.events.listByRun(run.id).map((e) => e.type);
    expect(events).toContain('tool.call.started');
    expect(events).toContain('tool.call.completed');
    const calls = repos.toolCalls.listByRun(run.id);
    expect(calls[0]!.status).toBe('completed');
    expect(calls[0]!.durationMs).not.toBeNull();
  });

  it('AC-18-02: abgebrochene Signale beenden den Aufruf', async () => {
    const controller = new AbortController();
    controller.abort();
    const { ctx } = setup(controller.signal);
    const outcome = await executeTool('open_url', { url: 'https://example.com' }, ctx, ['open_url']);
    expect(outcome.ok).toBe(false);
  });

  it('AC-18-03: Ergebnisse werden für das Modell gekürzt', () => {
    const text = toolResultForModel('web_search', {
      ok: true,
      result: { results: Array.from({ length: 200 }, () => ({ snippet: 'x'.repeat(200) })) },
    });
    expect(text).toContain('gekürzt');
  });

  it('Allowlist filtert die Registry', () => {
    expect(getToolsFor(['calculator']).map((t) => t.name)).toEqual(['calculator']);
    expect(getToolsFor([])).toHaveLength(0);
  });

  it('AC-18-02: Timeout beendet den Aufruf mit TOOL_TIMEOUT', async () => {
    const { ctx, repos, run } = setup();
    const slowTool = {
      name: 'calculator' as const,
      description: 'langsam',
      parameters: z.object({}),
      result: z.object({ ok: z.boolean() }),
      timeoutMs: 60,
      maxRetries: 0,
      costClass: 'free' as const,
      resultTokenBudget: 10,
      cacheable: false,
      execute: () => new Promise<{ ok: boolean }>(() => undefined),
      summarize: () => 'nie',
    };
    const started = Date.now();
    const outcome = await executeToolDefinition(slowTool as never, {}, ctx);
    expect(outcome.ok).toBe(false);
    if (!outcome.ok) expect(outcome.code).toBe('TOOL_TIMEOUT');
    expect(Date.now() - started).toBeLessThan(1000);
    const calls = repos.toolCalls.listByRun(run.id);
    expect(calls[0]!.status).toBe('failed');
    expect(repos.events.listByRun(run.id).map((e) => e.type)).toContain('tool.call.failed');
  });
});

import { describe, expect, it } from 'vitest';
import { assertUrlAllowed, canonicalizeUrl, isPrivateAddress, domainOf } from '@/lib/util/url-safety';

describe('Spec 39/20 — SSRF-Guard und URL-Normalisierung', () => {
  it('AC-39-01 / AC-20-01: Metadata-Endpunkt wird blockiert', async () => {
    await expect(assertUrlAllowed('http://169.254.169.254/latest/meta-data')).rejects.toMatchObject({
      appError: { code: 'FETCH_BLOCKED' },
    });
  });

  it('AC-47-03: Loopback ist nur mit Demo-Ausnahme erlaubt', async () => {
    await expect(assertUrlAllowed('http://127.0.0.1:3000/x')).rejects.toMatchObject({
      appError: { code: 'FETCH_BLOCKED' },
    });
    await expect(assertUrlAllowed('http://127.0.0.1:3000/x', { allowLoopback: true })).resolves.toBeInstanceOf(URL);
  });

  it('blockiert private Bereiche und interne Hostnamen', async () => {
    for (const url of ['http://10.0.0.5/', 'http://192.168.1.1/', 'http://172.16.4.4/', 'http://intranet.local/']) {
      await expect(assertUrlAllowed(url)).rejects.toMatchObject({ appError: { code: 'FETCH_BLOCKED' } });
    }
  });

  it('lehnt nicht-http(s)-Schemata ab', async () => {
    await expect(assertUrlAllowed('file:///etc/passwd')).rejects.toMatchObject({
      appError: { code: 'FETCH_BLOCKED' },
    });
  });

  it('erkennt private Adressen korrekt', () => {
    expect(isPrivateAddress('169.254.169.254', 4)).toBe(true);
    expect(isPrivateAddress('::1', 6)).toBe(true);
    expect(isPrivateAddress('93.184.216.34', 4)).toBe(false);
  });

  it('AC-19-01: Kanonisierung entfernt www, Tracking-Parameter und Fragment', () => {
    expect(canonicalizeUrl('https://WWW.Example.com/a/b/?utm_source=x&q=1#top'))
      .toBe('https://example.com/a/b?q=1');
    expect(canonicalizeUrl('https://example.com/a')).toBe(canonicalizeUrl('https://www.example.com/a'));
    expect(domainOf('https://www.bundesliga.example/x')).toBe('bundesliga.example');
  });
});

import { describe, expect, it } from 'vitest';
import { compareValues, normalizeValue, periodOf } from '@/lib/util/values';
import { detectConflicts } from '@/lib/agent/research/conflicts';
import type { ExtractionItem, SourceRecord } from '@/lib/contracts/domain';

function source(id: string, index: number, trust = 0.7): SourceRecord {
  return {
    id, runId: 'run_1', conversationId: 'cnv_1', indexNum: index,
    url: `https://q${index}.example/`, canonicalUrl: `https://q${index}.example`,
    domain: `q${index}.example`, title: `Quelle ${index}`, author: null,
    publishedAt: null, fetchedAt: null, sourceType: 'secondary', trustScore: trust,
    contentHash: null, rawTextLen: 100, status: 'fetched', note: null, createdAt: '',
  };
}

function item(claimKey: string, value: string, sourceId: string, excerpt = ''): ExtractionItem {
  return { claimKey, label: claimKey, value, excerpt, sourceId, confidence: 0.8 };
}

describe('Spec 28 — Widerspruchserkennung', () => {
  it('AC-28-01: „1,2 Mio." und „1200000" gelten als gleich', () => {
    expect(compareValues('1,2 Mio.', '1200000').equal).toBe(true);
    expect(normalizeValue('1,2 Mio. €').number).toBe(1_200_000);
    expect(normalizeValue('1,2 Mio. €').currency).toBe('EUR');
  });

  it('unterschiedliche Währungen sind ein Konflikt', () => {
    expect(compareValues('765 Mio. €', '765 Mio. USD')).toMatchObject({ equal: false, reason: 'currency_mismatch' });
  });

  it('Toleranz von 1 % gilt als Übereinstimmung', () => {
    expect(compareValues('1000', '1005').equal).toBe(true);
    expect(compareValues('1000', '1100').equal).toBe(false);
  });

  it('AC-28-02: abweichende Werte erzeugen einen Konflikt mit beiden Angaben', () => {
    const sources = [source('src_1', 1), source('src_2', 2, 0.5)];
    const result = detectConflicts(
      [item('bayern.umsatz', '765 Mio. €', 'src_1'), item('bayern.umsatz', '744 Mio. €', 'src_2')],
      sources, 0.01,
    );
    expect(result.conflicts).toHaveLength(1);
    expect(result.conflicts[0]!.entries.map((e) => e.index).sort()).toEqual([1, 2]);
    expect(result.conflicts[0]!.description).toContain('765');
    expect(result.conflicts[0]!.description).toContain('744');
    expect(result.conflicts[0]!.entries[0]!.trustScore).toBeGreaterThanOrEqual(result.conflicts[0]!.entries[1]!.trustScore);
  });

  it('AC-28-04: unterschiedliche Zeiträume sind kein Konflikt', () => {
    const sources = [source('src_1', 1), source('src_2', 2)];
    const result = detectConflicts(
      [
        item('bayern.umsatz', '765 Mio. €', 'src_1', 'Saison 2024/25 lag der Umsatz bei 765 Mio. €'),
        item('bayern.umsatz', '744 Mio. €', 'src_2', 'Saison 2025/26 lag der Umsatz bei 744 Mio. €'),
      ],
      sources, 0.01,
    );
    expect(result.conflicts).toHaveLength(0);
  });

  it('übereinstimmende Werte zählen als Bestätigung', () => {
    const sources = [source('src_1', 1), source('src_2', 2)];
    const result = detectConflicts(
      [item('musiala.tore', '14', 'src_1'), item('musiala.tore', '14', 'src_2')],
      sources, 0.01,
    );
    expect(result.conflicts).toHaveLength(0);
    expect(result.agreementCount).toBe(1);
    expect(result.agreementBySource.get('src_1')).toBe(1);
  });

  it('erkennt Zeiträume', () => {
    expect(periodOf('musiala.tore.2025_26')).toBeDefined();
    expect(periodOf('Saison 2025/26')).toBe('2025/26');
  });
});

